INSERT INTO rooms (id,nome,descricao,materia_id,assuntos,quantidade,dificuldade,tempo_por_questao,status) VALUES ('nivora_enem_v3_funcao_afim','Simulado de Função afim — ENEM','Preparação ENEM · 5 questões autorais de fundamentos, com explicações. Sem cronômetro. Não é prova oficial nem simulação da nota TRI.','matematica','["Função afim"]',5,'medio',0,'ACTIVE') ON CONFLICT(id) DO NOTHING;
INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v3_funcao_afim_q1','nivora_enem_v3_funcao_afim','Um serviço cobra R$ 8 de taxa fixa e R$ 2 por quilômetro. Qual função representa o custo C de x quilômetros?','A taxa fixa independe de x e entra como termo constante. O custo por quilômetro multiplica a distância.','Função afim',0,1) ON CONFLICT(id) DO NOTHING;
