INSERT INTO questions (id,room_id,enunciado,explicacao,assunto,ordem,correta_idx) VALUES ('nivora_enem_v3_genetica_q1','nivora_enem_v3_genetica','Em uma característica com dominância completa, A é dominante sobre a. Qual cruzamento produz apenas descendentes Aa?','O genitor AA só fornece A e o genitor aa só fornece a. Todos os descendentes serão Aa.','Genética mendeliana',0,0) ON CONFLICT(id) DO NOTHING;
